insert into public.curated_question_catalog
select * from jsonb_populate_recordset(null::public.curated_question_catalog, '[{"id":"2d94d56e-92c8-4511-a048-9798873eb887","state":"AC","subject":"Língua Portuguesa","subtopic":"Gêneros e tipologias textuais","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Gênero textual é forma social de comunicação; tipologia é modo de organização discursiva. Um mesmo gênero pode combinar narração, descrição, exposição e argumentação.","is_original":true,"legal_basis":["Língua Portuguesa — gêneros e tipologias textuais"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Gêneros textuais e tipologia","question_text":"Um relatório policial pode apresentar predominância narrativa ao reconstruir a sequência de fatos, mas também conter trechos descritivos e expositivos. A classificação do gênero não impede a combinação de diferentes tipologias textuais. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-PORT-001","import_unique_key":"a804550f9475f370c554d98b9d75d7aaf40336c5944ed672a810455e9488bd60","syllabus_topic_id":"4a545820-c8db-449d-b9d2-29009a5f32de","import_content_key":"a804550f9475f370c554d98b9d75d7aaf40336c5944ed672a810455e9488bd60","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"10f5af32-9b7c-4931-99f0-7446219a14e1","state":"AC","subject":"Língua Portuguesa","subtopic":"Coesão referencial","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"fácil","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O pronome oblíquo “os” retoma o sintagma nominal “os documentos” e funciona como objeto direto de “encaminhou”, contribuindo para a coesão referencial.","is_original":true,"legal_basis":["Língua Portuguesa — coesão referencial e pronomes"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Pronomes e retomada textual","question_text":"Leia: “A equipe recolheu os documentos e os encaminhou à perícia.” O pronome “os” retoma “os documentos”, evitando repetição e estabelecendo coesão referencial. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-PORT-002","import_unique_key":"1551217d327a5cbbd9dae711e078fb47ec88af2833dd54ff0094571488c52295","syllabus_topic_id":"4a545820-c8db-449d-b9d2-29009a5f32de","import_content_key":"1551217d327a5cbbd9dae711e078fb47ec88af2833dd54ff0094571488c52295","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"efbecd16-98d9-44be-b67d-94fcc22b1a55","state":"AC","subject":"Língua Portuguesa","subtopic":"Pontuação e orações adjetivas","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A oração adjetiva restritiva delimita o grupo de servidores. A pontuação pode transformá-la em explicativa, generalizando a referência e alterando a interpretação.","is_original":true,"legal_basis":["Língua Portuguesa — pontuação e orações subordinadas adjetivas"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Vírgula e restrição de sentido","question_text":"Em “Os servidores que concluíram o treinamento receberão certificado”, a oração “que concluíram o treinamento” é restritiva; a inserção de vírgulas antes e depois dela pode alterar o sentido ao apresentar a informação como explicativa. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-PORT-003","import_unique_key":"de050fa4ecbf209f658c2a5915bcdec2efb8876125f0e165c040cfc298d71813","syllabus_topic_id":"4a545820-c8db-449d-b9d2-29009a5f32de","import_content_key":"de050fa4ecbf209f658c2a5915bcdec2efb8876125f0e165c040cfc298d71813","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"8b2fc32c-d407-41f1-b4f6-24323a5902b0","state":"AC","subject":"Língua Portuguesa","subtopic":"Crase","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"fácil","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Quem encaminha algo encaminha a alguém; o termo feminino admite artigo: a autoridade. A fusão de a + a resulta em à.","is_original":true,"legal_basis":["Língua Portuguesa — regência e crase"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Emprego do acento grave","question_text":"Na frase “O relatório foi encaminhado à autoridade competente”, o emprego do acento grave está correto porque ocorre a fusão da preposição exigida por “encaminhar” com o artigo feminino que antecede “autoridade”. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-PORT-004","import_unique_key":"94799f8eaa04ad756b237fd40cbb07bafb5bd16a47f3c4fe14fdfcf30baed13a","syllabus_topic_id":"4a545820-c8db-449d-b9d2-29009a5f32de","import_content_key":"94799f8eaa04ad756b237fd40cbb07bafb5bd16a47f3c4fe14fdfcf30baed13a","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"cdb3d317-e1bb-4a6e-8fbe-4468ce66f720","state":"AC","subject":"Língua Portuguesa","subtopic":"Regência verbal","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"No sentido de ver/presenciar, assistir é transitivo indireto e exige a preposição “a”: assistir ao interrogatório. Em outros sentidos, a regência pode ser diferente.","is_original":true,"legal_basis":["Língua Portuguesa — regência verbal"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Regência de assistir e obedecer","question_text":"Na norma-padrão, no sentido de presenciar, o verbo “assistir” rege a preposição “a”; portanto, a construção “assistiu ao interrogatório” está adequada. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-PORT-005","import_unique_key":"867ad5d6d84bb34439d59830ec0cfef5902592b2685843de936012490d398a1e","syllabus_topic_id":"4a545820-c8db-449d-b9d2-29009a5f32de","import_content_key":"867ad5d6d84bb34439d59830ec0cfef5902592b2685843de936012490d398a1e","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"2acf6afe-95c0-4235-9075-c6c395876349","state":"AC","subject":"Língua Portuguesa","subtopic":"Colocação pronominal","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"fácil","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Palavras negativas são fatores de atração pronominal. Por isso, a colocação “não se divulgaram” atende à norma-padrão.","is_original":true,"legal_basis":["Língua Portuguesa — colocação pronominal"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Próclise por palavra negativa","question_text":"Na frase “Não se divulgaram os dados da investigação”, a próclise é adequada porque a palavra negativa “não” atrai o pronome oblíquo átono. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-PORT-006","import_unique_key":"cab9a3020fdb1d91a8964c89328c1e62102d39ef392c4584de314ed7a1b681a5","syllabus_topic_id":"4a545820-c8db-449d-b9d2-29009a5f32de","import_content_key":"cab9a3020fdb1d91a8964c89328c1e62102d39ef392c4584de314ed7a1b681a5","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"da7c5b1b-4ed3-4c68-a3fa-9f3224b60460","state":"AC","subject":"Língua Portuguesa","subtopic":"Ortografia — por que/porque/por quê/porquê","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"“Por que” separado introduz pergunta indireta ou causa interrogativa; “porquê” junto e acentuado é substantivo, normalmente acompanhado de artigo ou determinante.","is_original":true,"legal_basis":["Língua Portuguesa — ortografia oficial"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Emprego dos quatro porquês","question_text":"Complete corretamente: “A equipe não explicou ____ o sistema falhou; todos perguntaram o ____ da interrupção.”\n\nA) porque / por que\nB) porquê / porque\nC) por que / porquê\nD) por quê / porquê\nE) por que / por quê","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-PORT-007","import_unique_key":"883eebb0719998d979e526144af37a14e889f389ac616f5ddb624997eb53b892","syllabus_topic_id":"4a545820-c8db-449d-b9d2-29009a5f32de","import_content_key":"883eebb0719998d979e526144af37a14e889f389ac616f5ddb624997eb53b892","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"3a83888b-4732-403b-a815-77ec92d0203a","state":"AC","subject":"Língua Portuguesa","subtopic":"Acentuação gráfica","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"“Saída” recebe acento pelo hiato; “herói” é oxítona com ditongo aberto; “ideia” perdeu o acento após o Acordo Ortográfico. As demais alternativas contêm grafias antigas ou incorretas.","is_original":true,"legal_basis":["Acordo Ortográfico da Língua Portuguesa","Língua Portuguesa — acentuação gráfica"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Hiato e ditongo aberto","question_text":"Assinale a alternativa em que todas as palavras estão grafadas conforme a ortografia vigente:\n\nA) idéia, assembléia, heróico.\nB) saída, herói, ideia.\nC) vôo, enjôo, feiúra.\nD) rúbrica, gratuíto, raíz.\nE) assembléia, saúde, jóia.","content_status":"active","career_category":"policial","official_answer":"B","external_item_key":"NC-PCAC-PORT-008","import_unique_key":"790db10eb4c8aa90b50f558b851bcfff69f79b4ab4d8590a01f6c630deb20af8","syllabus_topic_id":"4a545820-c8db-449d-b9d2-29009a5f32de","import_content_key":"790db10eb4c8aa90b50f558b851bcfff69f79b4ab4d8590a01f6c630deb20af8","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"ef469b4b-b5d7-4a69-ba8d-6b43a4bbdb70","state":"AC","subject":"Língua Portuguesa","subtopic":"Morfologia — classes de palavras","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O “que” retoma o antecedente “documento” e introduz oração subordinada adjetiva. Pode ser substituído por “o qual”, o que confirma seu valor relativo.","is_original":true,"legal_basis":["Língua Portuguesa — morfologia e sintaxe"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Pronome relativo e conjunção integrante","question_text":"Em “O documento que foi apreendido será periciado”, o termo “que” retoma “documento” e exerce função de pronome relativo. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-PORT-009","import_unique_key":"b4cfaf17ee7ffb09aeff579af815038cec618e611edb442d3274bb4451bf36ff","syllabus_topic_id":"4a545820-c8db-449d-b9d2-29009a5f32de","import_content_key":"b4cfaf17ee7ffb09aeff579af815038cec618e611edb442d3274bb4451bf36ff","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"453d7f01-e5c4-4a82-aea9-e6cf041a4eca","state":"AC","subject":"Língua Portuguesa","subtopic":"Concordância verbal","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A expressão “mais de um” normalmente exige verbo no singular. Há casos especiais de reciprocidade ou repetição que podem alterar a concordância, mas não aparecem no enunciado.","is_original":true,"legal_basis":["Língua Portuguesa — concordância verbal"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Expressão mais de um","question_text":"Na norma-padrão, a frase “Mais de um servidor compareceu à unidade” apresenta concordância verbal adequada, pois a expressão “mais de um”, em regra, leva o verbo ao singular. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-PORT-010","import_unique_key":"25d158db4add7ce582291af27abf2c37dba519a289b47cf64ff1e9d664212dbc","syllabus_topic_id":"4a545820-c8db-449d-b9d2-29009a5f32de","import_content_key":"25d158db4add7ce582291af27abf2c37dba519a289b47cf64ff1e9d664212dbc","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"fae02508-d264-4743-986d-d671ed88421a","state":"AC","subject":"Noções de Direito Administrativo","subtopic":"Princípios expressos e implícitos","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"fácil","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O caput do art. 37 da Constituição enumera legalidade, impessoalidade, moralidade, publicidade e eficiência (LIMPE). Outros princípios são reconhecidos, mas não substituem esse rol expresso.","is_original":true,"legal_basis":["Constituição Federal, art. 37, caput"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Princípios da Administração Pública","question_text":"À luz do art. 37 da Constituição Federal, a atuação administrativa deve observar, entre outros, os princípios expressos de:\n\nA) legalidade, pessoalidade, moralidade, sigilo e eficiência.\nB) legalidade, impessoalidade, moralidade, publicidade e eficiência.\nC) autonomia, hierarquia, pessoalidade, publicidade e supremacia.\nD) legalidade, razoabilidade, sigilo, autotutela e eficiência.\nE) moralidade, informalidade, pessoalidade, publicidade e eficiência.","content_status":"active","career_category":"policial","official_answer":"B","external_item_key":"NC-PCAC-ADM-001","import_unique_key":"7724f8b72ff0789f1009f42037969a8100b2d34fec616c0cfe531c78b218f510","syllabus_topic_id":"ec1c0da0-edef-4e18-b70a-ad0bc4a88aea","import_content_key":"7724f8b72ff0789f1009f42037969a8100b2d34fec616c0cfe531c78b218f510","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":"2026-11-14T18:34:35.241426+00:00"},{"id":"ed9d767e-7438-4e85-90ba-d31eb4480b84","state":"AC","subject":"Noções de Direito Administrativo","subtopic":"Administração direta e indireta","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Autarquia é pessoa jurídica de direito público criada diretamente por lei específica para desempenhar atividade administrativa típica. Integra a Administração indireta e possui patrimônio e capacidade próprios.","is_original":true,"legal_basis":["Constituição Federal, art. 37, XIX","Decreto-Lei nº 200/1967, art. 5º, I"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Organização administrativa — autarquias e entidades","question_text":"Uma autarquia estadual é criada diretamente por lei específica, possui personalidade jurídica própria e integra a Administração indireta. Essa descrição está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-ADM-002","import_unique_key":"d6f8828c84a63f76a01f67dff0e79c057e3f37d49ed4dc53d5d93f9f3778369b","syllabus_topic_id":"ec1c0da0-edef-4e18-b70a-ad0bc4a88aea","import_content_key":"d6f8828c84a63f76a01f67dff0e79c057e3f37d49ed4dc53d5d93f9f3778369b","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":"2026-11-14T18:34:35.241426+00:00"},{"id":"e7f0e7e5-624a-45dd-9711-fdea75e457e5","state":"AC","subject":"Noções de Direito Administrativo","subtopic":"Centralização, descentralização e desconcentração","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Desconcentração distribui competências entre órgãos da mesma pessoa jurídica. Descentralização envolve outra pessoa jurídica, por outorga ou delegação.","is_original":true,"legal_basis":["Decreto-Lei nº 200/1967, arts. 4º e 10"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Organização administrativa e distribuição de competências","question_text":"A criação de departamentos dentro da mesma pessoa jurídica, com distribuição interna de competências, caracteriza:\n\nA) descentralização por colaboração.\nB) descentralização por outorga.\nC) desconcentração administrativa.\nD) privatização de serviço público.\nE) delegação contratual a particular.","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-ADM-003","import_unique_key":"e323c20f635f5ad29fb3a3567de7bc37d6902a9c721bfa18a3a41b32c895b355","syllabus_topic_id":"ec1c0da0-edef-4e18-b70a-ad0bc4a88aea","import_content_key":"e323c20f635f5ad29fb3a3567de7bc37d6902a9c721bfa18a3a41b32c895b355","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":"2026-11-14T18:34:35.241426+00:00"},{"id":"a466ab9f-3c32-4c84-8fc9-0d475e1aa0f0","state":"AC","subject":"Noções de Direito Administrativo","subtopic":"Poder hierárquico","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O poder hierárquico organiza a atuação interna e permite direção, fiscalização, delegação e avocação nos limites legais. A vinculação entre Administração direta e entidade da indireta não equivale a subordinação hierárquica.","is_original":true,"legal_basis":["Decreto-Lei nº 200/1967, art. 19","Princípios de organização administrativa"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Poderes administrativos — hierarquia","question_text":"No exercício do poder hierárquico, a autoridade superior pode distribuir e ordenar atividades, fiscalizar subordinados e rever atos nos limites legais. Esse poder, entretanto, não cria hierarquia entre pessoas jurídicas distintas da Administração direta e indireta. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-ADM-004","import_unique_key":"5e7b9971b6d5410f0ddb88984bbda1f2a3c0fba69c96395db9457a38b94ffb3d","syllabus_topic_id":"ec1c0da0-edef-4e18-b70a-ad0bc4a88aea","import_content_key":"5e7b9971b6d5410f0ddb88984bbda1f2a3c0fba69c96395db9457a38b94ffb3d","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":"2026-11-14T18:34:35.241426+00:00"},{"id":"b01a02d3-51fe-43ea-abad-7b7d2e6c5ba7","state":"AC","subject":"Noções de Direito Administrativo","subtopic":"Poder disciplinar","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O poder disciplinar alcança servidores e particulares sujeitos a vínculo especial, como contratados. Não é poder geral para punir qualquer cidadão; exige competência, previsão e devido processo.","is_original":true,"legal_basis":["Constituição Federal, art. 5º, LIV e LV","Lei nº 14.133/2021, regime sancionatório contratual"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Poder disciplinar e sanções administrativas","question_text":"O poder disciplinar permite à Administração apurar infrações e aplicar sanções a servidores e também a particulares que mantenham vínculo jurídico específico com a Administração, respeitados o devido processo e a defesa. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-ADM-005","import_unique_key":"f3ebd654ffdf84b27f30cd5476512c160a8c57ceaa9e13afc5f62e855af2d962","syllabus_topic_id":"ec1c0da0-edef-4e18-b70a-ad0bc4a88aea","import_content_key":"f3ebd654ffdf84b27f30cd5476512c160a8c57ceaa9e13afc5f62e855af2d962","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":"2026-11-14T18:34:35.241426+00:00"},{"id":"93f950cf-1864-4bf3-ae44-15ee85deb9e9","state":"AC","subject":"Noções de Direito Administrativo","subtopic":"Poder de polícia","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O poder de polícia limita ou disciplina direitos, interesses ou liberdades em razão do interesse público. O ciclo clássico abrange ordem, consentimento, fiscalização e sanção, observadas as competências e limites legais.","is_original":true,"legal_basis":["Código Tributário Nacional, art. 78","STF, RE 633.782, Tema 532"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Poder de polícia — ciclo e atributos","question_text":"O poder de polícia administrativa pode condicionar ou restringir direitos e atividades em benefício do interesse público, nos limites legais. Em sua formulação clássica, o ciclo de polícia compreende ordem, consentimento, fiscalização e sanção. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-ADM-006","import_unique_key":"db01c68dbac4d5706ad76dd9fbb8e9975e86506afc008529cd72d24e34b039e7","syllabus_topic_id":"ec1c0da0-edef-4e18-b70a-ad0bc4a88aea","import_content_key":"db01c68dbac4d5706ad76dd9fbb8e9975e86506afc008529cd72d24e34b039e7","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":"2026-11-14T18:34:35.241426+00:00"},{"id":"eda7c3e0-b128-4e93-be8b-f20a699e1aac","state":"AC","subject":"Noções de Direito Administrativo","subtopic":"Atributos dos atos administrativos","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A presunção de legitimidade/veracidade é relativa. Imperatividade e autoexecutoriedade não aparecem em todos os atos; a execução direta depende de autorização legal ou situação urgente admitida pelo ordenamento.","is_original":true,"legal_basis":["Direito Administrativo — teoria dos atos administrativos"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Presunção, imperatividade e autoexecutoriedade","question_text":"Sobre os atributos dos atos administrativos, assinale a alternativa correta:\n\nA) Todo ato possui imperatividade e autoexecutoriedade.\nB) A presunção de legitimidade é absoluta.\nC) A autoexecutoriedade autoriza execução material em qualquer hipótese, sem previsão legal ou urgência.\nD) A presunção de legitimidade é relativa e admite prova em contrário.\nE) A imperatividade está presente em todos os atos negociais e enunciativos.","content_status":"active","career_category":"policial","official_answer":"D","external_item_key":"NC-PCAC-ADM-007","import_unique_key":"b9c8a4eff68476dcd74d1aeb9fc0e1c8d8389b7656aaf75b33838b07889b5075","syllabus_topic_id":"ec1c0da0-edef-4e18-b70a-ad0bc4a88aea","import_content_key":"b9c8a4eff68476dcd74d1aeb9fc0e1c8d8389b7656aaf75b33838b07889b5075","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":"2026-11-14T18:34:35.241426+00:00"},{"id":"c726386b-31e0-4529-9387-5f8de84da969","state":"AC","subject":"Noções de Direito Administrativo","subtopic":"Anulação e revogação","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"fácil","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A retirada de ato ilegal é anulação, fundada em controle de legalidade. Revogação é retirada de ato válido por conveniência e oportunidade, respeitados direitos adquiridos e limites legais.","is_original":true,"legal_basis":["Súmula 473 do STF","Constituição Federal, art. 37"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Autotutela administrativa","question_text":"A Administração identifica que um ato foi praticado com ilegalidade e decide retirá-lo do ordenamento. Em regra, a providência adequada é a revogação por conveniência e oportunidade?","content_status":"active","career_category":"policial","official_answer":"E","external_item_key":"NC-PCAC-ADM-008","import_unique_key":"d12fc7b46e0ca8ef05836495d4f08d920c63e516cea2a503f4d05a8b864b8a0b","syllabus_topic_id":"ec1c0da0-edef-4e18-b70a-ad0bc4a88aea","import_content_key":"d12fc7b46e0ca8ef05836495d4f08d920c63e516cea2a503f4d05a8b864b8a0b","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":"2026-11-14T18:34:35.241426+00:00"},{"id":"9ad365e2-e7bd-4fd0-9683-7f9891ec8c7a","state":"AC","subject":"Noções de Direito Administrativo","subtopic":"Agentes públicos e acumulação","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"São as hipóteses excepcionais do art. 37, XVI, da Constituição. A compatibilidade de horários é requisito indispensável; a acumulação fora das exceções é vedada.","is_original":true,"legal_basis":["Constituição Federal, art. 37, XVI e XVII"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Acumulação constitucional de cargos","question_text":"A Constituição admite, havendo compatibilidade de horários e observância do teto constitucional, a acumulação remunerada de dois cargos de professor, de um cargo de professor com outro técnico ou científico, ou de dois cargos/empregos privativos de profissionais de saúde com profissões regulamentadas. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-ADM-009","import_unique_key":"eca9375920f6ed18af0743e2dfc8593bf4020165a27c178550752c3a250dc86d","syllabus_topic_id":"ec1c0da0-edef-4e18-b70a-ad0bc4a88aea","import_content_key":"eca9375920f6ed18af0743e2dfc8593bf4020165a27c178550752c3a250dc86d","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":"2026-11-14T18:34:35.241426+00:00"},{"id":"5bb3ce5a-2286-42b4-9be5-0753e83cd695","state":"AC","subject":"Noções de Direito Administrativo","subtopic":"Responsabilidade civil do Estado","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O art. 37, § 6º, da Constituição adota a responsabilidade objetiva da pessoa jurídica perante a vítima, com base no dano e nexo causal, assegurando regresso contra o responsável nos casos de dolo ou culpa.","is_original":true,"legal_basis":["Constituição Federal, art. 37, § 6º"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Responsabilidade objetiva e direito de regresso","question_text":"A pessoa jurídica estatal responde objetivamente pelos danos que seus agentes, nessa qualidade, causarem a terceiros; o direito de regresso contra o agente depende de dolo ou culpa. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-ADM-010","import_unique_key":"b3564c8675b2b153f84920068912dba39f33e0f5b45ffcf8ac18dca77a85fba5","syllabus_topic_id":"ec1c0da0-edef-4e18-b70a-ad0bc4a88aea","import_content_key":"b3564c8675b2b153f84920068912dba39f33e0f5b45ffcf8ac18dca77a85fba5","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":"2026-11-14T18:34:35.241426+00:00"},{"id":"5de1e396-2428-41f8-bf7e-25131a9c17a9","state":"AC","subject":"Raciocínio Lógico","subtopic":"Negação de proposições compostas","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Pela lei de De Morgan, a negação de uma conjunção p ∧ q é ¬p ∨ ¬q. Basta que uma das partes seja falsa para negar a conjunção.","is_original":true,"legal_basis":["Lógica proposicional — leis de De Morgan"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Leis de De Morgan","question_text":"A negação lógica de “A equipe revisou o relatório e encaminhou os anexos” é “A equipe não revisou o relatório ou não encaminhou os anexos”. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-RLM-001","import_unique_key":"80af548a621f9f9be4eadea4489956c7045df2ab0b217a2acf41b6abdf602e2c","syllabus_topic_id":"92f3abc8-e74d-4eb2-9263-23e16e39d1d5","import_content_key":"80af548a621f9f9be4eadea4489956c7045df2ab0b217a2acf41b6abdf602e2c","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"fb3854fb-71c4-4504-8ff7-4eafafeadabe","state":"AC","subject":"Raciocínio Lógico","subtopic":"Equivalências lógicas","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A condicional p → q é equivalente à contrapositiva ¬q → ¬p. Não é equivalente à conversa q → p.","is_original":true,"legal_basis":["Lógica proposicional — equivalência da contrapositiva"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Contrapositiva da condicional","question_text":"A proposição “Se o sistema está autenticado, então o acesso é permitido” é logicamente equivalente à sua contrapositiva: “Se o acesso não é permitido, então o sistema não está autenticado”. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-RLM-002","import_unique_key":"153c396b8f13a754e67fc8f9a45f49fdb635c47f57128c8391bafce65f659fef","syllabus_topic_id":"92f3abc8-e74d-4eb2-9263-23e16e39d1d5","import_content_key":"153c396b8f13a754e67fc8f9a45f49fdb635c47f57128c8391bafce65f659fef","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"6e922fd4-fefd-4231-8e20-135c5efae566","state":"AC","subject":"Raciocínio Lógico","subtopic":"Bicondicional e tabela-verdade","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"fácil","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O bicondicional expressa equivalência lógica: é verdadeiro em V↔V e F↔F, e falso em V↔F e F↔V.","is_original":true,"legal_basis":["Lógica proposicional — tabela-verdade do bicondicional"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Conectivo bicondicional","question_text":"A proposição bicondicional p ↔ q é verdadeira quando p e q possuem o mesmo valor lógico e falsa quando possuem valores diferentes. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-RLM-003","import_unique_key":"53fe1dacb5c8b53ad8ce21caabd998ca84b4db7e4d3be66800488da06d6a3697","syllabus_topic_id":"92f3abc8-e74d-4eb2-9263-23e16e39d1d5","import_content_key":"53fe1dacb5c8b53ad8ce21caabd998ca84b4db7e4d3be66800488da06d6a3697","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"c45bcc73-3abf-4a4c-976c-d53a4b453fd9","state":"AC","subject":"Raciocínio Lógico","subtopic":"Quantificadores e negação","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A negação de uma universal é existencial: “Existe pelo menos um relatório que não foi revisado”. “Nenhum” é mais forte e não representa a negação lógica exata.","is_original":true,"legal_basis":["Lógica de predicados — quantificadores"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Negação de proposição universal","question_text":"A negação de “Todos os relatórios foram revisados” é “Nenhum relatório foi revisado”. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"E","external_item_key":"NC-PCAC-RLM-004","import_unique_key":"187290d2dc319a089f712c39ace86873d48a48add25d22115b22cf2414f4fafd","syllabus_topic_id":"92f3abc8-e74d-4eb2-9263-23e16e39d1d5","import_content_key":"187290d2dc319a089f712c39ace86873d48a48add25d22115b22cf2414f4fafd","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"35850c09-c388-4802-9cdb-aded96e05593","state":"AC","subject":"Raciocínio Lógico","subtopic":"Conjuntos e operações","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Pela inclusão-exclusão: |P ∪ R| = 24 + 18 − 10 = 32. Portanto, a resposta correta é C.","is_original":true,"legal_basis":["Teoria dos conjuntos — princípio da inclusão-exclusão"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"União, interseção e princípio da inclusão-exclusão","question_text":"Em uma turma de 40 candidatos, 24 estudam Português, 18 estudam Raciocínio Lógico e 10 estudam ambas as disciplinas. Quantos estudam pelo menos uma das duas?\n\nA) 28\nB) 30\nC) 32\nD) 34\nE) 36","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-RLM-005","import_unique_key":"2c9eb0eddc0d8dfc47bf815836ad61b08cfeafd0de12f9ff10d65070d5d54754","syllabus_topic_id":"92f3abc8-e74d-4eb2-9263-23e16e39d1d5","import_content_key":"2c9eb0eddc0d8dfc47bf815836ad61b08cfeafd0de12f9ff10d65070d5d54754","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"b4084349-a39b-4879-894a-b2942476a4f4","state":"AC","subject":"Raciocínio Lógico","subtopic":"Porcentagem","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Os descontos são sucessivos: preço final = 0,80 × 0,90 = 0,72 do preço inicial. O desconto total é 28%, não 30%.","is_original":true,"legal_basis":["Matemática básica — porcentagem e descontos sucessivos"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Descontos sucessivos","question_text":"Um equipamento sofre desconto de 20% e, sobre o preço já reduzido, recebe novo desconto de 10%. O desconto total equivale a 30% do preço original. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"E","external_item_key":"NC-PCAC-RLM-006","import_unique_key":"068d7655f0407f56fa3f33b1e6af5bd9e35c7379f02aec7c1d53196a7be3c404","syllabus_topic_id":"92f3abc8-e74d-4eb2-9263-23e16e39d1d5","import_content_key":"068d7655f0407f56fa3f33b1e6af5bd9e35c7379f02aec7c1d53196a7be3c404","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"5785836a-3dda-4e53-8882-f7c290ac355d","state":"AC","subject":"Raciocínio Lógico","subtopic":"Juros simples","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"fácil","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"J = C × i × t = 2.000 × 0,02 × 5 = R$ 200,00. O montante é R$ 2.200,00.","is_original":true,"legal_basis":["Matemática financeira — juros simples"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Cálculo de juros simples","question_text":"Um capital de R$ 2.000,00 aplicado a juros simples de 2% ao mês durante 5 meses produz juros de R$ 200,00. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-RLM-007","import_unique_key":"ef79d91aed34fee598f68a53412fde77dd5d3633c1baaddf64b8bd01677838b0","syllabus_topic_id":"92f3abc8-e74d-4eb2-9263-23e16e39d1d5","import_content_key":"ef79d91aed34fee598f68a53412fde77dd5d3633c1baaddf64b8bd01677838b0","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"a59938bd-e9f7-4cc6-b5c7-3938212de872","state":"AC","subject":"Raciocínio Lógico","subtopic":"Análise combinatória","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Como a ordem não importa, utiliza-se combinação: C(5,3) = 5!/(3!2!) = 10.","is_original":true,"legal_basis":["Análise combinatória — combinação simples"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Combinação simples","question_text":"Uma equipe será formada por 3 servidores escolhidos entre 5 candidatos, sem distinção de cargos ou ordem. O número de equipes possíveis é 10. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-RLM-008","import_unique_key":"e95af49a70e84413e289b9923de3c8e1cb903b1fead8e2fa2b14c00474e174b8","syllabus_topic_id":"92f3abc8-e74d-4eb2-9263-23e16e39d1d5","import_content_key":"e95af49a70e84413e289b9923de3c8e1cb903b1fead8e2fa2b14c00474e174b8","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"3a97d6cf-8525-44db-ae11-1ffcbe62884d","state":"AC","subject":"Raciocínio Lógico","subtopic":"Probabilidade","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"fácil","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Há 5 bolas no total e 3 são vermelhas. Logo, P(não azul) = 3/5, ou 60%.","is_original":true,"legal_basis":["Probabilidade — evento complementar e espaço amostral"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Probabilidade complementar","question_text":"Em uma caixa há 3 bolas vermelhas e 2 azuis. Ao retirar uma bola ao acaso, a probabilidade de não sair azul é 3/5. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-RLM-009","import_unique_key":"e5d4bc8e97e6965fbbd9a07f5c15a7dc9a967adaaffeacfda4191fceeb9854c5","syllabus_topic_id":"92f3abc8-e74d-4eb2-9263-23e16e39d1d5","import_content_key":"e5d4bc8e97e6965fbbd9a07f5c15a7dc9a967adaaffeacfda4191fceeb9854c5","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null},{"id":"f8d4bbce-dee1-42a2-b6a8-518c65548b28","state":"AC","subject":"Raciocínio Lógico","subtopic":"Média aritmética e ponderada","role_type":"Oficial Investigador de Polícia","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","created_at":"2026-11-14T18:34:35.241426+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Média ponderada = (6×2 + 8×3)/(2+3) = 36/5 = 7,2.","is_original":true,"legal_basis":["Estatística básica — médias aritmética e ponderada"],"verified_at":"2026-11-14T18:34:35.241426+00:00","contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Média ponderada","question_text":"Um candidato obteve nota 6 em uma prova de peso 2 e nota 8 em outra de peso 3. Sua média ponderada é 7,2. A afirmação está correta?","content_status":"active","career_category":"policial","official_answer":"C","external_item_key":"NC-PCAC-RLM-010","import_unique_key":"b55ca262aa6d02d772f3e4cfdc73469da1c322ac9f6f0f69f215ad521c799b09","syllabus_topic_id":"92f3abc8-e74d-4eb2-9263-23e16e39d1d5","import_content_key":"b55ca262aa6d02d772f3e4cfdc73469da1c322ac9f6f0f69f215ad521c799b09","didactic_provenance":{"batch":"Fase 2 — núcleo de matérias pendentes, lote 01","origin":"Norte Concursos — questão autoral","is_original":true,"review_date":"2026-11-14","target_exam":"PC-AC 2026 — Oficial Investigador de Polícia","source_basis":"Edital nº 001/2026 SEAD/PCAC — Anexo III","target_style":"IDECAN"},"law_version_checked_at":null}]'::jsonb)
